def run(path, keys=b':q\r', rows=20, cols=70):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    env=os.environ.copy(); env['TERM']='xterm-256color'; env['HOME']=tempfile.mkdtemp(prefix='fxhome_')
