def run(path, keys, env_extra):
    master, slave=pty.openpty(); fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',16,80,0,0))
    env=os.environ.copy(); env['TERM']='xterm-256color'; env['HOME']=tempfile.mkdtemp(prefix='fxhome_'); env.update(env_extra)
    p=subprocess.Popen(['/workspace/executable', path], stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
