        if p.poll() is not None:
            break
    try: os.close(master)
    except: pass
    return p.poll(), out

td=tempfile.mkdtemp(prefix='fxshell_'); os.mkdir(os.path.join(td,'sub'))
rd=tempfile.mkdtemp(prefix='fxrt_')
for name, keys in [('colon_q', b'l:q\r'), ('ZZ', b'lZZ'), ('ZQ', b'lZQ')]:
    # clean runtime
    for f in os.listdir(rd): os.unlink(os.path.join(rd,f))
