INIT_TEXT = r'''# To be eval'ed in the calling shell
  eval "$(
    if [ -n "$XDG_RUNTIME_DIR" ]; then
      runtime_dir="$XDG_RUNTIME_DIR/felix"
    elif [ -n "$TMPDIR" ]; then
      runtime_dir="$TMPDIR/felix"
    else
      runtime_dir=/tmp/felix
    fi

    mkdir -p "$runtime_dir"

    # Clean up leftover LWD files
    find "$runtime_dir" -type f -and -mmin +1 -delete

    cat << EOF
fx() {
  local RUNTIME_DIR="$runtime_dir"
  SHELL_PID=\$\$ command fx "\$@"

  if [ -f "\$RUNTIME_DIR/\$\$" ]; then
    cd "\$(cat "\$RUNTIME_DIR/\$\$")"
    rm "\$RUNTIME_DIR/\$\$"
  fi
}
EOF
  )"
'''

ESC = "\x1b"
RESET = f"{ESC}[0m"
INV = f"{ESC}[7m"
HIDE = f"{ESC}[?25l"
SHOW = f"{ESC}[?25h"


def c256(n: int) -> str:
    return f"{ESC}[38;5;{n}m"


def bg256(n: int) -> str:
    return f"{ESC}[48;5;{n}m"


def ioctl_terminal_size(fd: int = 1) -> Optional[Tuple[int, int]]:
    try:
        import struct
        data = fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH", 0, 0, 0, 0))
        rows, cols, _xp, _yp = struct.unpack("HHHH", data)
        if rows > 0 and cols > 0:
            return rows, cols
    except Exception:
        pass
    return None


def data_home() -> str:
    base = os.environ.get("XDG_DATA_HOME")
    if not base:
        base = os.path.join(os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, "felix")


def config_home() -> str:
    base = os.environ.get("XDG_CONFIG_HOME")
    if not base:
        base = os.path.join(os.path.expanduser("~"), ".config")
    return os.path.join(base, "felix")


def runtime_dir() -> str:
    if os.environ.get("XDG_RUNTIME_DIR"):
        return os.path.join(os.environ["XDG_RUNTIME_DIR"], "felix")
    if os.environ.get("TMPDIR"):
        return os.path.join(os.environ["TMPDIR"], "felix")
    return "/tmp/felix"


def bool_from_string(s: str) -> Optional[bool]:
    s = s.strip().lower()
    if s in ("true", "yes", "on", "1"):
        return True
    if s in ("false", "no", "off", "0"):
        return False
    return None


def read_simple_yaml(path: str) -> Dict[str, str]:
    out: Dict[str, str] = {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or ":" not in line:
                    continue
                k, v = line.split(":", 1)
                out[k.strip()] = v.strip().strip('"\'')
    except Exception:
        pass
    return out


def size_string(n: int) -> str:
    try:
        n = int(n)
    except Exception:
        n = 0
    units = ["B", "KB", "MB", "GB", "TB"]
    value = float(n)
    unit = 0
    while abs(value) >= 1000.0 and unit < len(units) - 1:
        value /= 1000.0
        unit += 1
    if unit == 0:
        return f"{int(value)}B"
    return f"{int(value)}{units[unit]}"


def perm_string(mode: int) -> str:
    return format(stat.S_IMODE(mode) & 0o777, "o")


def mtime_string(path: str) -> str:
    try:
        return _dt.datetime.fromtimestamp(os.lstat(path).st_mtime).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return "0000-00-00 00:00"


def file_ext(name: str) -> str:
    if name.startswith(".") and name.count(".") == 1:
        return ""
    base, ext = os.path.splitext(name)
    if ext.startswith(".") and len(ext) > 1:
        return ext[1:]
    return ""


def is_text_bytes(data: bytes) -> bool:
    if b"\x00" in data:
        return False
    try:
        data.decode("utf-8")
        return True
    except Exception:
        try:
            data.decode("latin1")
            return True
        except Exception:
            return False


def unique_path(directory: str, name: str, split_ext: bool = True) -> str:
    candidate = os.path.join(directory, name)
    if not os.path.exists(candidate) and not os.path.lexists(candidate):
        return candidate
    if split_ext:
        stem, ext = os.path.splitext(name)
        if not stem:  # names like .profile should not become _1.profile
            stem, ext = name, ""
    else:
        stem, ext = name, ""
    i = 1
    while True:
        candidate = os.path.join(directory, f"{stem}_{i}{ext}")
        if not os.path.exists(candidate) and not os.path.lexists(candidate):
            return candidate
        i += 1


def copy_item(src: str, dest: str) -> None:
    if os.path.islink(src):
        target = os.readlink(src)
        os.symlink(target, dest)
        try:
            shutil.copystat(src, dest, follow_symlinks=False)
        except Exception:
            pass
    elif os.path.isdir(src):
        shutil.copytree(src, dest, symlinks=True)
    else:
        shutil.copy2(src, dest, follow_symlinks=False)


def remove_item(path: str) -> None:
    if os.path.islink(path) or os.path.isfile(path):
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass
    elif os.path.isdir(path):
        shutil.rmtree(path, ignore_errors=True)


def maybe_realpath(path: str) -> str:
    try:
        return os.path.realpath(path)
    except Exception:
        return os.path.abspath(path)


def find_git_branch(path: str) -> Optional[str]:
    cur = os.path.abspath(path)
    while True:
        git = os.path.join(cur, ".git")
        head_path = os.path.join(git, "HEAD")
        try:
            if os.path.isfile(head_path):
                with open(head_path, "r", encoding="utf-8", errors="ignore") as f:
                    head = f.read().strip()
                if head.startswith("ref: refs/heads/"):
                    return head[len("ref: refs/heads/"):]
                if head:
                    return head[:7]
        except Exception:
            return None
        parent = os.path.dirname(cur)
        if parent == cur:
            return None
        cur = parent


@dataclass
class Entry:
    name: str
    path: str
    is_dir: bool
    is_symlink: bool
    stat: Optional[os.stat_result]


class Terminal:
    def __init__(self) -> None:
        self.in_fd = 0
        self.out_fd = 1
        self.old_attrs = None

    def write(self, s: str) -> None:
        os.write(self.out_fd, s.encode("utf-8", errors="replace"))

    def flush(self) -> None:
        try:
            sys.stdout.flush()
        except Exception:
            pass

    def __enter__(self) -> "Terminal":
        try:
            self.old_attrs = termios.tcgetattr(self.in_fd)
            tty.setraw(self.in_fd)
        except Exception:
            self.old_attrs = None
        self.write(f"{ESC}7{HIDE}{ESC}[?1049h")
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.write(f"{HIDE}{ESC}[?1049l{ESC}8{SHOW}")
        if self.old_attrs is not None:
            try:
                termios.tcsetattr(self.in_fd, termios.TCSADRAIN, self.old_attrs)
            except Exception:
                pass


class KeyReader:
    def __init__(self, fd: int = 0) -> None:
        self.fd = fd
        self.buffer = b""

    def _read_byte(self) -> bytes:
        if self.buffer:
            b, self.buffer = self.buffer[:1], self.buffer[1:]
            return b
        return os.read(self.fd, 1)

    def _read_available(self, timeout: float = 0.015) -> bytes:
        chunks = []
        while True:
            r, _, _ = select.select([self.fd], [], [], timeout)
            if not r:
                break
            try:
                chunk = os.read(self.fd, 32)
            except BlockingIOError:
                break
            if not chunk:
                break
            chunks.append(chunk)
            timeout = 0.001
            if len(chunk) < 32:
                # still allow a very small chance for the final byte of CSI
                continue
        return b"".join(chunks)

    def read_key(self) -> str:
        b = self._read_byte()
        if not b:
            return ""
        if b == b"\x1b":
            rest = self._read_available()
            if not rest:
                return "esc"
            if rest.startswith(b"["):
                if rest in (b"[A", b"OA"):
                    return "up"
                if rest in (b"[B", b"OB"):
                    return "down"
                if rest in (b"[C", b"OC"):
                    return "right"
                if rest in (b"[D", b"OD"):
                    return "left"
                if rest.startswith(b"[1;3B") or rest.startswith(b"[3B"):
                    return "alt_down"
                if rest.startswith(b"[1;3A") or rest.startswith(b"[3A"):
                    return "alt_up"
                return "escseq:" + rest.decode("ascii", "ignore")
            try:
                ch = rest.decode("utf-8")
            except Exception:
                ch = ""
            if ch == "j":
                return "alt_down"
            if ch == "k":
                return "alt_up"
            return "alt_" + ch if ch else "esc"
        if b in (b"\r", b"\n"):
            return "enter"
        if b in (b"\x7f", b"\x08"):
            return "backspace"
        if b == b"\x04":
            return "ctrl_d"
        if b == b"\x15":
            return "ctrl_u"
        if b == b"\x12":
            return "ctrl_r"
        if b == b"\x0f":
            return "ctrl_o"
        if b == b"\x09":
            return "ctrl_i"
        if b == b"\x03":
            return "ctrl_c"
        # UTF-8 continuation support for simple non-ASCII names.
        first = b[0]
        needed = 0
        if 0xC0 <= first <= 0xDF:
            needed = 1
        elif 0xE0 <= first <= 0xEF:
            needed = 2
        elif 0xF0 <= first <= 0xF7:
            needed = 3
        if needed:
            more = b""
            for _ in range(needed):
                r, _, _ = select.select([self.fd], [], [], 0.01)
                if r:
                    more += os.read(self.fd, 1)
            b += more
        try:
            return b.decode("utf-8")
        except Exception:
            return ""


class FelixApp:
    def __init__(self, start_path: str, log_enabled: bool = False) -> None:
        self.launch_cwd = os.getcwd()
        self.cwd = maybe_realpath(start_path)
        self.term = Terminal()
        self.keys = KeyReader()
        self.rows, self.cols = ioctl_terminal_size(1) or (24, 80)
        self.base_data = data_home()
        self.trash = os.path.join(self.base_data, "Trash")
        self.log_enabled = log_enabled
        self.log_path: Optional[str] = None
        self.entries: List[Entry] = []
        self.selected = 0
        self.offset = 0
        self.message = ""
        self.message_error = False
        self.sort_by = "Name"
        self.show_hidden = True
        self.preview = False
        self.split = "Vertical"
        self.search_query = ""
        self.search_matches: List[int] = []
        self.preview_scroll = 0
        self.history: List[str] = [self.cwd]
        self.history_pos = 0
        self.registers: Dict[str, List[Dict[str, object]]] = {"0": []}
        self.undo_stack: List[Dict[str, object]] = []
        self.redo_stack: List[Dict[str, object]] = []
        self.visual = False
        self.visual_anchor = 0
        self.exit_requested = False
        self.write_lwd_on_exit = False
        self.match_vim_exit_behavior = False
        self.config_dir = config_home()
        self.load_config_and_session()
        self.ensure_dirs()
        self.reload()

    def ensure_dirs(self) -> None:
        try:
            os.makedirs(self.trash, exist_ok=True)
        except Exception:
            pass
        if os.environ.get("SHELL_PID"):
            try:
                os.makedirs(runtime_dir(), exist_ok=True)
            except Exception:
                pass
        if self.log_enabled:
            try:
                log_dir = os.path.join(self.base_data, "log")
                os.makedirs(log_dir, exist_ok=True)
                stamp = _dt.datetime.now().strftime("%Y-%m-%d-%H-%M-%S")
                self.log_path = os.path.join(log_dir, f"{stamp}.log")
                self.log("===START===")
            except Exception:
                self.log_path = None

    def load_config_and_session(self) -> None:
        # Packaged behavior stores last UI toggles in $XDG_DATA_HOME/felix/.session.
        # Config files are parsed leniently for common keys.
        for cfg_name in ("config.yaml", "config.yml"):
            cfg_path = os.path.join(self.config_dir, cfg_name)
            if os.path.exists(cfg_path):
                cfg = read_simple_yaml(cfg_path)
                self.apply_settings(cfg)
                break
        session = os.path.join(self.base_data, ".session")
        if os.path.exists(session):
            self.apply_settings(read_simple_yaml(session))

    def apply_settings(self, settings: Dict[str, str]) -> None:
        for k, v in settings.items():
            key = k.strip()
            val = v.strip()
            if key in ("sort_by", "sort"):
                if val.lower().startswith("time") or val.lower().startswith("modified"):
                    self.sort_by = "Time"
                elif val.lower().startswith("name"):
                    self.sort_by = "Name"
            elif key == "show_hidden":
                b = bool_from_string(val)
                if b is not None:
                    self.show_hidden = b
            elif key == "preview":
                b = bool_from_string(val)
                if b is not None:
                    self.preview = b
            elif key == "split":
                if val.lower().startswith("h"):
                    self.split = "Horizontal"
                elif val.lower().startswith("v"):
                    self.split = "Vertical"
            elif key == "match_vim_exit_behavior":
                b = bool_from_string(val)
                if b is not None:
                    self.match_vim_exit_behavior = b

    def save_session(self) -> None:
        try:
            os.makedirs(self.base_data, exist_ok=True)
            with open(os.path.join(self.base_data, ".session"), "w", encoding="utf-8") as f:
                f.write(f"sort_by: {self.sort_by}\n")
                f.write(f"show_hidden: {'true' if self.show_hidden else 'false'}\n")
                f.write(f"preview: {'true' if self.preview else 'false'}\n")
                f.write(f"split: {self.split}\n")
        except Exception:
            pass

    def log(self, msg: str) -> None:
        if not self.log_path:
            return
        try:
            stamp = _dt.datetime.now().strftime("%H:%M:%S")
            with open(self.log_path, "a", encoding="utf-8") as f:
                f.write(f"{stamp} [INFO] {msg}\n")
        except Exception:
            pass

    def finish(self) -> None:
        self.save_session()
        if self.write_lwd_on_exit and os.environ.get("SHELL_PID"):
            try:
                rd = runtime_dir()
                os.makedirs(rd, exist_ok=True)
                with open(os.path.join(rd, os.environ["SHELL_PID"]), "w", encoding="utf-8") as f:
                    f.write(self.cwd)
            except Exception:
                pass
        self.log("===FINISH===")

    def refresh_size(self) -> None:
        size = ioctl_terminal_size(1)
        if size:
            self.rows, self.cols = size

    def visible_capacity(self) -> int:
        if self.preview and self.split == "Horizontal":
            return max(1, (self.rows - 3) // 2)
        return max(1, self.rows - 3)

    def list_width(self) -> int:
        if self.preview and self.split == "Vertical":
            return max(20, self.cols // 2)
        return self.cols

    def reload(self, keep_name: Optional[str] = None) -> None:
        items: List[Entry] = []
        try:
            with os.scandir(self.cwd) as it:
                for de in it:
                    name = de.name
                    if not self.show_hidden and name.startswith("."):
                        continue
                    try:
                        lst = de.stat(follow_symlinks=False)
                    except Exception:
                        lst = None
                    try:
                        is_dir = de.is_dir(follow_symlinks=True)
                    except Exception:
                        is_dir = False
                    try:
                        is_lnk = de.is_symlink()
                    except Exception:
                        is_lnk = False
                    items.append(Entry(name=name, path=os.path.join(self.cwd, name), is_dir=is_dir, is_symlink=is_lnk, stat=lst))
        except Exception as e:
            self.entries = []
            self.message = str(e)
            self.message_error = True
            return

        if self.sort_by == "Time":
            items.sort(key=lambda e: ((0 if e.is_dir else 1), -(e.stat.st_mtime if e.stat else 0), e.name.lower()))
        else:
            items.sort(key=lambda e: ((0 if e.is_dir else 1), e.name.lower()))
        self.entries = items
        if keep_name:
            for i, e in enumerate(items):
                if e.name == keep_name:
                    self.selected = i
                    break
        if not self.entries:
            self.selected = 0
            self.offset = 0
        else:
            self.selected = min(max(self.selected, 0), len(self.entries) - 1)
            self.ensure_visible()
        self.update_search_matches(select_first=False)

    def ensure_visible(self) -> None:
        cap = self.visible_capacity()
        if self.selected < self.offset:
            self.offset = self.selected
        elif self.selected >= self.offset + cap:
            self.offset = self.selected - cap + 1
        max_off = max(0, len(self.entries) - cap)
        self.offset = max(0, min(self.offset, max_off))

    def selected_entry(self) -> Optional[Entry]:
        if 0 <= self.selected < len(self.entries):
            return self.entries[self.selected]
        return None

    def selected_entries(self) -> List[Entry]:
        if not self.visual or not self.entries:
            e = self.selected_entry()
            return [e] if e else []
        a, b = sorted((self.visual_anchor, self.selected))
        return self.entries[a:b + 1]

    def status_text(self) -> str:
        if self.search_query:
            count = len(self.search_matches)
            return f" /{self.search_query} - {count} {'match' if count == 1 else 'matches'}"
        e = self.selected_entry()
        if not e:
            return ""
        if e.is_symlink:
            try:
                target = os.readlink(e.path)
                if not os.path.isabs(target):
                    target = os.path.normpath(os.path.join(self.cwd, target))
                return f" linked to: {target}"
            except Exception:
                pass
        try:
            st = os.lstat(e.path)
        except Exception:
            return f" {self.selected + 1}/{len(self.entries)}"
        prefix = f" {self.selected + 1}/{len(self.entries)} "
        ext = file_ext(e.name) if not e.is_dir else ""
        if ext:
            prefix += ext + " "
        return prefix + f"{size_string(st.st_size)} {perm_string(st.st_mode)}"

    def draw_status(self) -> None:
        self.term.write(f"{ESC}[{self.rows};1H{ESC}[2K{RESET}{INV}" + " " * self.cols + RESET)
        st = self.status_text()
        if st:
            self.term.write(f"{ESC}[{self.rows};1H{INV}{st}{RESET}")

    def draw_header(self) -> None:
        path = self.cwd
        self.term.write(f"{ESC}[1;1H{c256(6)} {path}{RESET}")
        try:
            if not os.access(self.cwd, os.W_OK):
                self.term.write(f"{c256(1)} [RO]{RESET}")
        except Exception:
            pass
        branch = find_git_branch(self.cwd)
        if branch:
            self.term.write(f" on {c256(13)}{ESC}[1m{branch}{RESET}{RESET}")

    def draw_entries(self) -> None:
        cap = self.visible_capacity()
        width = self.list_width()
        date_col_move = max(1, width - 17)
        for idx in range(self.offset, min(len(self.entries), self.offset + cap)):
            e = self.entries[idx]
            row = 3 + (idx - self.offset)
            color = 14 if e.is_dir and not e.is_symlink else (11 if e.is_symlink else 15)
            # If the item cannot be stat'ed, make it red-ish like inaccessible items.
            if e.stat is None:
                color = 1
            bold = self.search_query and self.search_query.lower() in e.name.lower()
            name = e.name
            max_name = max(1, width - 22)
            if len(name) > max_name:
                name = name[:max_name - 1] + "…"
            style = c256(color) + (f"{ESC}[1m" if bold else "")
            self.term.write(f"{ESC}[{row};3H{style}{name}{RESET}")
            self.term.write(f"{ESC}[1000D{ESC}[{date_col_move}C {mtime_string(e.path)}{RESET}")
        # The original leaves the cursor/selector at the selected line using this byte pattern.
        if self.entries:
            row = 3 + (self.selected - self.offset)
            if 3 <= row <= self.rows - 1:
                self.term.write(f"{ESC}[{row};1H>{ESC}[1D {ESC}[1D")
        else:
            self.term.write(f"{ESC}[3;1H>{ESC}[1D")

    def preview_lines_for(self, e: Optional[Entry]) -> List[Tuple[str, int]]:
        if not e:
            return []
        lines: List[Tuple[str, int]] = []
        if e.is_dir:
            lines.append((f"[{e.name}]", 15))
            try:
                names = sorted(os.listdir(e.path), key=lambda s: s.lower())[:200]
                for i, name in enumerate(names):
                    prefix = "└ " if i == len(names) - 1 else "├ "
                    lines.append((prefix + name, 8))
            except Exception as exc:
                lines.append((str(exc), 1))
            return lines
        try:
            with open(e.path, "rb") as f:
                data = f.read(64 * 1024)
            if not is_text_bytes(data):
                lines.append((f"[{e.name}]", 15))
                lines.append(("Binary file", 8))
                return lines
            text = data.decode("utf-8", errors="replace")
            lines.append((f"[{e.name}]", 15))
            for line in text.splitlines()[:400]:
                lines.append((line, 8))
        except Exception as exc:
            lines.append((str(exc), 1))
        return lines

    def draw_preview(self) -> None:
        if not self.preview:
            return
        e = self.selected_entry()
        lines = self.preview_lines_for(e)
        if self.split == "Vertical":
            start_col = self.list_width() + 1
            width = max(1, self.cols - start_col)
            for r in range(1, self.rows + 1):
                self.term.write(f"{ESC}[{r};{start_col}H{ESC}[K")
            for i, (txt, color) in enumerate(lines[self.preview_scroll:self.preview_scroll + self.rows - 1]):
                row = 1 + i
                if len(txt) > width - 1:
                    txt = txt[:width - 2] + "…"
                pad = " " if row == 1 else ""
                self.term.write(f"{ESC}[{row};{start_col}H{pad}{c256(color)}{txt}{RESET}")
        else:
            start_row = max(4, 3 + self.visible_capacity() + 1)
            for r in range(start_row, self.rows):
                self.term.write(f"{ESC}[{r};1H{ESC}[K")
            for i, (txt, color) in enumerate(lines[self.preview_scroll:self.preview_scroll + (self.rows - start_row)]):
                row = start_row + i
                if len(txt) > self.cols - 2:
                    txt = txt[:self.cols - 3] + "…"
                self.term.write(f"{ESC}[{row};2H{c256(color)}{txt}{RESET}")

    def draw_message(self) -> None:
        if not self.message:
            return
        style = f"{c256(7)}{bg256(9)}" if self.message_error else ""
        self.term.write(f"{ESC}[2;2H{ESC}[2K{style}{self.message}{RESET}{HIDE}")

    def draw(self) -> None:
        self.refresh_size()
        self.ensure_visible()
        self.term.write(f"{HIDE}{ESC}[2J")
        self.draw_header()
        self.draw_entries()
        self.draw_status()
        self.draw_preview()
        self.draw_message()

    def prompt_line(self, prompt: str, initial: str = "") -> Optional[str]:
        buf = list(initial)
        pos = len(buf)
        self.term.write(f"{ESC}[2;2H{ESC}[2K{prompt}{''.join(buf)}{SHOW}")
        while True:
            self.term.write(f"{ESC}[2;{2 + len(prompt) + pos}H")
            k = self.keys.read_key()
            if k in ("enter",):
                self.term.write(HIDE)
                return "".join(buf)
            if k in ("esc", "ctrl_c"):
                self.term.write(HIDE)
                return None
            if k == "backspace":
                if pos > 0:
                    pos -= 1
                    del buf[pos]
            elif k == "left":
                pos = max(0, pos - 1)
            elif k == "right":
                pos = min(len(buf), pos + 1)
            elif k == "ctrl_r":
                reg = self.keys.read_key()
                entries = self.registers.get(reg, [])
                text = " ".join(str(x.get("name", os.path.basename(str(x.get("path", ""))))) for x in entries)
                for ch in text:
                    buf.insert(pos, ch)
                    pos += 1
            elif len(k) == 1 and (k >= " " or ord(k) >= 128):
                buf.insert(pos, k)
                pos += 1
            self.term.write(f"{ESC}[2;2H{ESC}[2K{prompt}{''.join(buf)}")

    def set_message(self, msg: str, error: bool = False) -> None:
        self.message = msg
        self.message_error = error

    def move_selection(self, delta: int) -> None:
        if not self.entries:
            return
        self.selected = max(0, min(len(self.entries) - 1, self.selected + delta))
        self.ensure_visible()

    def go_parent(self) -> None:
        parent = os.path.dirname(self.cwd.rstrip(os.sep)) or os.sep
        if parent == self.cwd:
            return
        old_name = os.path.basename(self.cwd)
        self.cwd = parent
        self.push_history(self.cwd)
        self.reload(keep_name=old_name)

    def enter_selected(self) -> None:
        e = self.selected_entry()
        if not e:
            return
        if e.is_dir:
            self.cwd = maybe_realpath(e.path)
            self.push_history(self.cwd)
            self.selected = 0
            self.offset = 0
            self.reload()
        else:
            # The real app delegates to an opener.  A no-op is safest in tests.
            self.set_message("")

    def push_history(self, path: str) -> None:
        if self.history and self.history[self.history_pos] == path:
            return
        self.history = self.history[:self.history_pos + 1]
        self.history.append(path)
        self.history_pos = len(self.history) - 1

    def history_back(self) -> None:
        if self.history_pos > 0:
            self.history_pos -= 1
            self.cwd = self.history[self.history_pos]
            self.reload()

    def history_forward(self) -> None:
        if self.history_pos < len(self.history) - 1:
            self.history_pos += 1
            self.cwd = self.history[self.history_pos]
            self.reload()

    def register_set(self, reg: str, entries: List[Dict[str, object]], append: bool = False) -> None:
        if append and reg in self.registers:
            self.registers[reg].extend(entries)
        else:
            self.registers[reg] = entries
        self.registers["0"] = list(self.registers[reg])

    def yank(self, reg: str = "0", append: bool = False) -> None:
        selected = self.selected_entries()
        if not selected:
            return
        ents = [{"path": e.path, "name": e.name, "deleted": False} for e in selected]
        self.register_set(reg, ents, append=append)
        self.visual = False
        self.set_message(f"{len(ents)} item{'s' if len(ents) != 1 else ''} yanked.")

    def delete(self, reg: str = "0", append: bool = False) -> None:
        selected = self.selected_entries()
        if not selected:
            return
        trash_entries: List[Dict[str, object]] = []
        undo_entries: List[Dict[str, object]] = []
        self.set_message("DELETE: Processing...")
        for e in selected:
            if not os.path.lexists(e.path):
                continue
            tname = f"{int(time.time() * 1000000000) % 2147483647}_{e.name}"
            tpath = unique_path(self.trash, tname, split_ext=False)
            try:
                shutil.move(e.path, tpath)
                ent = {"path": tpath, "name": e.name, "deleted": True}
                trash_entries.append(ent)
                undo_entries.append({"trash": tpath, "dest": os.path.join(self.cwd, e.name), "name": e.name})
            except Exception as exc:
                self.set_message(str(exc), True)
        if trash_entries:
            self.register_set(reg, trash_entries, append=append)
            self.undo_stack.append({"type": "delete", "entries": undo_entries})
            self.redo_stack.clear()
        self.visual = False
        self.reload()
        self.set_message(f"{len(trash_entries)} item{'s' if len(trash_entries) != 1 else ''} deleted. [0.00s]")

    def put(self, reg: str = "0") -> None:
        entries = self.registers.get(reg, [])
        if not entries:
            return
        inserted: List[str] = []
        self.set_message("PUT: Processing...")
        for ent in entries:
            src = str(ent.get("path", ""))
            name = str(ent.get("name") or os.path.basename(src))
            if not os.path.lexists(src):
                continue
            split = (not os.path.isdir(src)) and (not os.path.islink(src))
            dest = unique_path(self.cwd, name, split_ext=split)
            try:
                copy_item(src, dest)
                inserted.append(dest)
            except Exception as exc:
                self.set_message(str(exc), True)
        if inserted:
            self.undo_stack.append({"type": "put", "paths": inserted})
            self.redo_stack.clear()
        self.reload()
        self.set_message(f"{len(inserted)} item{'s' if len(inserted) != 1 else ''} inserted. [0.00s]")

    def undo(self) -> None:
        if not self.undo_stack:
            return
        op = self.undo_stack.pop()
        typ = op.get("type")
        if typ == "put":
            paths = list(op.get("paths", []))
            for p in paths:
                remove_item(str(p))
            self.redo_stack.append(op)
            self.reload()
            self.set_message("UNDONE: PUT")
        elif typ == "delete":
            restored = []
            for ent in op.get("entries", []):
                trash_p = str(ent.get("trash"))
                dest = str(ent.get("dest"))
                if os.path.lexists(trash_p) and not os.path.lexists(dest):
                    try:
                        copy_item(trash_p, dest)
                        restored.append(dest)
                    except Exception:
                        pass
            self.redo_stack.append(op)
            self.reload()
            self.set_message("UNDONE: DELETE")
        elif typ == "rename":
            old = str(op.get("old"))
            new = str(op.get("new"))
            if os.path.lexists(new):
                try:
                    os.rename(new, old)
                except Exception:
                    pass
            self.redo_stack.append(op)
            self.reload(keep_name=os.path.basename(old))
            self.set_message("UNDONE: RENAME")

    def redo(self) -> None:
        if not self.redo_stack:
            return
        op = self.redo_stack.pop()
        typ = op.get("type")
        if typ == "put":
            # A redo of put re-copies from the register if possible.
            self.put("0")
            return
        if typ == "delete":
            ents = []
            for ent in op.get("entries", []):
                dest = str(ent.get("dest"))
                name = str(ent.get("name", os.path.basename(dest)))
                if os.path.lexists(dest):
                    tpath = unique_path(self.trash, f"{int(time.time()*1000000000)%2147483647}_{name}", split_ext=False)
                    try:
                        shutil.move(dest, tpath)
                        ents.append({"trash": tpath, "dest": dest, "name": name})
                    except Exception:
                        pass
            if ents:
                newop = {"type": "delete", "entries": ents}
                self.undo_stack.append(newop)
                self.reload()
                self.set_message("REDONE: DELETE")
        if typ == "rename":
            old = str(op.get("old"))
            new = str(op.get("new"))
            if os.path.lexists(old):
                try:
                    os.rename(old, new)
                    self.undo_stack.append(op)
                    self.reload(keep_name=os.path.basename(new))
                    self.set_message("REDONE: RENAME")
                except Exception:
                    pass

    def create_file(self) -> None:
        self.draw()
        name = self.prompt_line("New file: ")
        if not name:
            return
        path = os.path.join(self.cwd, name)
        try:
            # Rust's File::create creates/truncates; this reproduces the simple visible effect.
            with open(path, "a", encoding="utf-8"):
                pass
            self.reload(keep_name=os.path.basename(path))
        except Exception as exc:
            self.set_message(str(exc), True)

    def create_dir(self) -> None:
        self.draw()
        name = self.prompt_line("New directory: ")
        if not name:
            return
        path = os.path.join(self.cwd, name)
        try:
            os.mkdir(path)
            self.reload(keep_name=os.path.basename(path))
        except Exception as exc:
            self.set_message(str(exc), True)

    def rename_current(self) -> None:
        e = self.selected_entry()
        if not e:
            return
        self.draw()
        new_name = self.prompt_line("Rename: ", e.name)
        if not new_name or new_name == e.name:
            return
        new_path = os.path.join(self.cwd, new_name)
        try:
            os.rename(e.path, new_path)
            self.undo_stack.append({"type": "rename", "old": e.path, "new": new_path})
            self.redo_stack.clear()
            self.reload(keep_name=new_name)
        except Exception as exc:
            self.set_message(str(exc), True)

    def update_search_matches(self, select_first: bool = False) -> None:
        if not self.search_query:
            self.search_matches = []
            return
        q = self.search_query.lower()
        self.search_matches = [i for i, e in enumerate(self.entries) if q in e.name.lower()]
        if select_first and self.search_matches:
            # Choose the first match at or after the current selection, otherwise wrap.
            for idx in self.search_matches:
                if idx >= self.selected:
                    self.selected = idx
                    break
            else:
                self.selected = self.search_matches[0]
            self.ensure_visible()

    def search(self) -> None:
        self.draw()
        q = self.prompt_line("/")
        if q is None:
            return
        self.search_query = q
        self.update_search_matches(select_first=True)
        self.set_message("")

    def search_next(self, backwards: bool = False) -> None:
        if not self.search_query:
            return
        self.update_search_matches(select_first=False)
        if not self.search_matches:
            return
        curpos = 0
        for i, idx in enumerate(self.search_matches):
            if idx == self.selected:
                curpos = i
                break
            if idx > self.selected:
                curpos = i - (1 if backwards else 0)
                break
        if backwards:
            self.selected = self.search_matches[(curpos - 1) % len(self.search_matches)]
        else:
            self.selected = self.search_matches[(curpos + 1) % len(self.search_matches)]
        self.ensure_visible()

    def cd_to(self, path: str) -> None:
        if not path:
            target = os.path.expanduser("~")
        else:
            expanded = os.path.expanduser(path)
            if os.path.isabs(expanded):
                target = expanded
            else:
                # Observed behavior resolves :cd relative to the process launch cwd.
                target = os.path.abspath(os.path.join(self.launch_cwd, expanded))
        if os.path.isdir(target):
            self.cwd = maybe_realpath(target)
            self.push_history(self.cwd)
            self.selected = 0
            self.offset = 0
            self.reload()
        else:
            self.set_message("Path does not exist.", True)

    def command_line(self) -> None:
        self.draw()
        cmd = self.prompt_line(":")
        if cmd is None:
            return
        stripped = cmd.strip()
        if stripped == "q":
            self.exit_requested = True
            return
        if stripped == "e":
            self.reload()
            return
        if stripped == "h":
            self.help_pager()
            return
        if stripped == "reg":
            parts = []
            for k in sorted(self.registers):
                vals = self.registers[k]
                if vals:
                    parts.append(f'"{k}: ' + ", ".join(str(v.get("name", "")) for v in vals))
            self.set_message(" | ".join(parts) if parts else "No registers.")
            return
        if stripped.startswith("cd") and (stripped == "cd" or stripped.startswith("cd ")):
            self.cd_to(stripped[2:].strip())
            return
        if stripped == "trash":
            try:
                os.makedirs(self.trash, exist_ok=True)
            except Exception:
                pass
            self.cwd = self.trash
            self.push_history(self.cwd)
            self.selected = 0
            self.offset = 0
            self.reload()
            return
        if stripped == "empty":
            self.term.write(f"{ESC}[2;2H{ESC}[2K{c256(7)}{bg256(9)}Are you sure to empty the trash directory? (if yes: y){RESET}{HIDE}")
            k = self.keys.read_key()
            if k == "y":
                try:
                    for name in os.listdir(self.trash):
                        remove_item(os.path.join(self.trash, name))
                    self.reload()
                    self.set_message("Trash directory emptied.")
                except Exception as exc:
                    self.set_message(str(exc), True)
            return
        if stripped == "config":
            if os.path.isdir(self.config_dir):
                self.cwd = self.config_dir
                self.push_history(self.cwd)
                self.reload()
            else:
                self.set_message("Config file does not exist.", True)
            return
        if not stripped:
            return
        # Arbitrary shell command in the current directory.
        try:
            completed = subprocess.run(stripped, shell=True, cwd=self.cwd)
            self.reload()
            if completed.returncode != 0:
                self.set_message("Command execution failed.", True)
        except Exception:
            self.set_message("Command execution failed.", True)

    def help_pager(self) -> None:
        lines = HELP_TEXT.splitlines()
        top = 0
        while True:
            self.term.write(f"{HIDE}{ESC}[2J")
            for i, line in enumerate(lines[top:top + self.rows - 1]):
                self.term.write(f"{ESC}[{i + 1};1H{line[:self.cols]}")
            if top + self.rows - 1 < len(lines):
                self.term.write(f"{ESC}[{self.rows};1H{INV}...{RESET}")
            k = self.keys.read_key()
            if k in ("q", "esc", "enter"):
                self.draw()
                return
            if k in ("j", "down", "ctrl_d"):
                top = min(max(0, len(lines) - 1), top + (self.rows // 2 if k == "ctrl_d" else 1))
            elif k in ("k", "up", "ctrl_u"):
                top = max(0, top - (self.rows // 2 if k == "ctrl_u" else 1))
            elif k == "G":
                top = max(0, len(lines) - self.rows + 1)
            elif k == "g":
                k2 = self.keys.read_key()
                if k2 == "g":
                    top = 0

    def change_home_or_zoxide(self) -> None:
        self.draw()
        query = self.prompt_line("z ")
        if query is None:
            return
        if not query.strip():
            self.cd_to(os.path.expanduser("~"))
            return
        # If zoxide is present use it, otherwise emit the same kind of harmless error message.
        try:
            result = subprocess.run(["zoxide", "query", query.strip()], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            if result.returncode == 0 and result.stdout.strip() and os.path.isdir(result.stdout.strip()):
                self.cwd = maybe_realpath(result.stdout.strip())
                self.push_history(self.cwd)
                self.reload()
                return
        except Exception:
            pass
        self.set_message("zoxide query failed.", True)

    def extract_selected(self) -> None:
        e = self.selected_entry()
        if not e or e.is_dir:
            return
        src = e.path
        lower = e.name.lower()
        self.set_message("Unpacking...")
        self.draw_message()
        start = time.time()
        try:
            if lower.endswith(".zip"):
                outdir = unique_path(self.cwd, e.name, split_ext=False)
                os.makedirs(outdir, exist_ok=False)
                with zipfile.ZipFile(src) as zf:
                    zf.extractall(outdir)
            elif lower.endswith((".tar", ".tar.gz", ".tgz", ".tar.xz", ".txz", ".tar.bz2", ".tbz2")):
                outdir = unique_path(self.cwd, e.name, split_ext=False)
                os.makedirs(outdir, exist_ok=False)
                with tarfile.open(src, "r:*") as tf:
                    tf.extractall(outdir)
            elif lower.endswith(".tar.zst") or lower.endswith(".tzst"):
                outdir = unique_path(self.cwd, e.name, split_ext=False)
                os.makedirs(outdir, exist_ok=False)
                data = self.decompress_zstd_file(src)
                with tarfile.open(fileobj=io.BytesIO(data), mode="r:") as tf:
                    tf.extractall(outdir)
            elif lower.endswith(".gz"):
                dest = unique_path(self.cwd, e.name, split_ext=False)
                with gzip.open(src, "rb") as f, open(dest, "wb") as out:
                    shutil.copyfileobj(f, out)
            elif lower.endswith(".xz"):
                dest = unique_path(self.cwd, e.name, split_ext=False)
                with lzma.open(src, "rb") as f, open(dest, "wb") as out:
                    shutil.copyfileobj(f, out)
            elif lower.endswith(".bz2"):
                dest = unique_path(self.cwd, e.name, split_ext=False)
                with bz2.open(src, "rb") as f, open(dest, "wb") as out:
                    shutil.copyfileobj(f, out)
            else:
                self.set_message("Unsupported archive.", True)
                return
            self.reload()
            self.set_message(f"Unpacked. [{time.time() - start:.2f}s]")
        except Exception as exc:
            self.reload()
            self.set_message(f"Unpack failed: {exc}", True)

    def decompress_zstd_file(self, path: str) -> bytes:
        with open(path, "rb") as f:
            src = f.read()
        libname = ctypes.util.find_library("zstd")
        if not libname:
            raise RuntimeError("zstd not available")
        lib = ctypes.CDLL(libname)
        lib.ZSTD_getFrameContentSize.argtypes = [ctypes.c_void_p, ctypes.c_size_t]
        lib.ZSTD_getFrameContentSize.restype = ctypes.c_ulonglong
        lib.ZSTD_decompress.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
        lib.ZSTD_decompress.restype = ctypes.c_size_t
        lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
        lib.ZSTD_isError.restype = ctypes.c_uint
        size = lib.ZSTD_getFrameContentSize(src, len(src))
        unknown = (1 << 64) - 1
        error = (1 << 64) - 2
        if size not in (unknown, error) and size > 0:
            capacities = [int(size)]
        else:
            capacities = []
        cap = max(len(src) * 8, 1024 * 1024)
        for _ in range(12):
            capacities.append(cap)
            cap *= 2
        srcbuf = ctypes.create_string_buffer(src)
        for capacity in capacities:
            dst = ctypes.create_string_buffer(capacity)
            res = lib.ZSTD_decompress(dst, capacity, srcbuf, len(src))
            if not lib.ZSTD_isError(res):
                return dst.raw[:res]
        raise RuntimeError("zstd decompression failed")

    def toggle_hidden(self) -> None:
        current = self.selected_entry().name if self.selected_entry() else None
        self.show_hidden = not self.show_hidden
        self.reload(keep_name=current)

    def toggle_sort(self) -> None:
        current = self.selected_entry().name if self.selected_entry() else None
        self.sort_by = "Time" if self.sort_by == "Name" else "Name"
        self.reload(keep_name=current)

    def handle_quote_command(self) -> None:
        reg = self.keys.read_key()
        if not reg:
            return
        append = reg.isupper()
        reg = reg.lower()
        op = self.keys.read_key()
        if op == "y":
            op2 = self.keys.read_key()
            if op2 == "y":
                self.yank(reg, append)
        elif op == "d":
            op2 = self.keys.read_key()
            if op2 == "d":
                self.delete(reg, append)
        elif op == "p":
            self.put(reg)
        elif self.visual:
            if op == "y":
                self.yank(reg, append)
            elif op == "d":
                self.delete(reg, append)

    def normal_loop(self) -> None:
        pending: Optional[str] = None
        while not self.exit_requested:
            self.draw()
            k = self.keys.read_key()
            if not k:
                continue
            if k == "ctrl_c":
                self.exit_requested = True
                break
            if pending == "g":
                if k == "g":
                    self.selected = 0
                    self.ensure_visible()
                pending = None
                continue
            if pending == "d":
                if k == "d":
                    self.delete()
                pending = None
                continue
            if pending == "y":
                if k == "y":
                    self.yank()
                pending = None
                continue
            if pending == "Z":
                if k == "Z":
                    if self.match_vim_exit_behavior:
                        self.write_lwd_on_exit = True
                    self.exit_requested = True
                elif k == "Q":
                    if not self.match_vim_exit_behavior:
                        self.write_lwd_on_exit = True
                    self.exit_requested = True
                pending = None
                continue

            if k in ("j", "down"):
                self.move_selection(1)
            elif k in ("k", "up"):
                self.move_selection(-1)
            elif k == "ctrl_d":
                self.move_selection(max(1, self.visible_capacity() // 2))
            elif k == "ctrl_u":
                self.move_selection(-max(1, self.visible_capacity() // 2))
            elif k in ("h", "left"):
                self.go_parent()
            elif k in ("l", "right", "enter"):
                self.enter_selected()
            elif k == "G":
                if self.entries:
                    self.selected = len(self.entries) - 1
                    self.ensure_visible()
            elif k == "g":
                pending = "g"
                self.term.write(f"{ESC}[2;2H{ESC}[2Kg{SHOW}")
            elif k == "d":
                if self.visual:
                    self.delete()
                else:
                    pending = "d"
                    self.term.write(f"{ESC}[2;2H{ESC}[2Kd{SHOW}")
            elif k == "y":
                if self.visual:
                    self.yank()
                else:
                    pending = "y"
                    self.term.write(f"{ESC}[2;2H{ESC}[2Ky{SHOW}")
            elif k == "p":
                self.put()
            elif k == '"':
                self.handle_quote_command()
            elif k == "V":
                self.visual = not self.visual
                self.visual_anchor = self.selected
            elif k == "u":
                self.undo()
            elif k == "ctrl_r":
                self.redo()
            elif k == "v":
                self.preview = not self.preview
                self.preview_scroll = 0
            elif k == "s":
                self.split = "Horizontal" if self.split == "Vertical" else "Vertical"
            elif k == "backspace":
                self.toggle_hidden()
            elif k == "t":
                self.toggle_sort()
            elif k == "c":
                self.rename_current()
            elif k == "/":
                self.search()
            elif k == "n":
                self.search_next(False)
            elif k == "N":
                self.search_next(True)
            elif k == ":":
                self.command_line()
            elif k == "i":
                self.create_file()
            elif k == "I":
                self.create_dir()
            elif k == "o":
                self.enter_selected()
            elif k == "e":
                self.extract_selected()
            elif k == "z":
                # The immediate z<CR> form is accepted by reading a line; empty means home.
                self.change_home_or_zoxide()
            elif k == "ctrl_o":
                self.history_back()
            elif k == "ctrl_i":
                self.history_forward()
            elif k == "alt_down":
                self.preview_scroll += 1
            elif k == "alt_up":
                self.preview_scroll = max(0, self.preview_scroll - 1)
            elif k == "Z":
                pending = "Z"
                self.term.write(f"{ESC}[2;2H{ESC}[2KZ{SHOW}")
            elif k == "esc":
                self.visual = False
                self.search_query = ""
                self.search_matches = []
                self.set_message("")

    def run(self) -> int:
        with self.term:
            self.normal_loop()
        self.finish()
        return 0


def print_invalid_path(path: str) -> None:
    # Observed: invalid path cases emit a bare newline to stdout before stderr.
    sys.stdout.write("\n")
    sys.stdout.flush()
    sys.stderr.write(f"Invalid path: {path}\n`fx -h` shows help.\n")
    sys.stderr.flush()


def print_not_directory() -> None:
    sys.stderr.write("Path should be directory.\n`fx -h` shows help.\n")
    sys.stderr.flush()


def parse_and_run(argv: Sequence[str]) -> int:
    args = list(argv)
    log_enabled = False
    path: Optional[str] = None

    if len(args) == 0:
        path = "."
    elif len(args) == 1:
        a = args[0]
        if a in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT)
            return 0
        if a == "--init":
            sys.stdout.write(INIT_TEXT)
            return 0
        if a in ("-l", "--log"):
            log_enabled = True
            path = "."
        else:
            path = a
    elif len(args) == 2:
        if args[0] in ("-l", "--log"):
            log_enabled = True
            path = args[1]
        else:
            sys.stdout.write(HELP_TEXT)
            return 0
    else:
        sys.stdout.write(HELP_TEXT)
        return 0

    assert path is not None
    if not os.path.exists(path):
        print_invalid_path(path)
        return 0
    if not os.path.isdir(path):
        print_not_directory()
        return 0

    if ioctl_terminal_size(1) is None:
        sys.stderr.write("Error: Cannot detect terminal size\n")
        sys.stderr.flush()
        return 0

    try:
        app = FelixApp(path, log_enabled=log_enabled)
        return app.run()
    except KeyboardInterrupt:
        return 0
    except Exception as exc:
        # The original tends to print user-facing errors rather than nonzero exits.
        try:
            sys.stderr.write(f"Error: {exc}\n")
        except Exception:
            pass
        return 0


def main() -> int:
    return parse_and_run(sys.argv[1:])


if __name__ == "__main__":
    raise SystemExit(main())
